export const saleLineItems = sqliteTable('sale_line_items', {
  id: text('id').primaryKey(),
  saleId: text('sale_id').notNull().references(() => sales.id),
  ...lineItemColumns,
  ...bicycleLineColumns,
  createdAt: integer('created_at', { mode: 'number' }).$defaultFn(() => Date.now()).notNull(),
}, (table) => ({
  saleIdIdx: index('sale_line_items_sale_id_idx').on(table.saleId),
  ...lineItemChecks(),
}))

export type SaleLineItem = typeof saleLineItems.$inferSelect
export type NewSaleLineItem = typeof saleLineItems.$inferInsert

/** Optional legal/financial snapshot from a Sale — immutable copy of line items */
export const invoices = sqliteTable('invoices', {
  id: text('id').primaryKey(),
  invoiceNumber: text('invoice_number').notNull().unique(), // INV-0001
  saleId: text('sale_id').notNull().unique().references(() => sales.id),
  customerId: text('customer_id').references(() => customers.id), // denormalized from sale for lookup
  status: text('status', { enum: ['issued', 'sent'] }).notNull().default('issued'),
  subtotalNet: integer('subtotal_net', { mode: 'number' }).notNull(),
  vatTotal: integer('vat_total', { mode: 'number' }).notNull(),
  totalGross: integer('total_gross', { mode: 'number' }).notNull(),
  issuedAt: integer('issued_at', { mode: 'timestamp' }).$defaultFn(() => new Date()).notNull(),
}, (table) => ({
  customerIdIdx: index('invoices_customer_id_idx').on(table.customerId),
}))

export type Invoice = typeof invoices.$inferSelect
export type NewInvoice = typeof invoices.$inferInsert

export type Repair = typeof repairs.$inferSelect
export type NewRepair = typeof repairs.$inferInsert

/** Repair line items — parts used and labor logged. minutesWorked is billing-specific; workLogs is the source of truth for actual time worked (payroll). */
export const repairLineItems = sqliteTable('repair_line_items', {
  id: text('id').primaryKey(),
  repairId: text('repair_id').notNull().references(() => repairs.id),
  ...lineItemColumns,
  minutesWorked: integer('minutes_worked', { mode: 'number' }), // billing minutes; may differ from workLogs (payroll)
  hourlyRateSnapshot: integer('hourly_rate_snapshot', { mode: 'number' }), // worker's rate at time of logging
  createdAt: integer('created_at', { mode: 'number' }).$defaultFn(() => Date.now()).notNull(),
}, (table) => ({
  repairIdIdx: index('repair_line_items_repair_id_idx').on(table.repairId),
  ...lineItemChecks(),
}))

export type RepairLineItem = typeof repairLineItems.$inferSelect
export type NewRepairLineItem = typeof repairLineItems.$inferInsert

/** Timer sessions per repair — source of truth for actual time worked (payroll). Billing minutes are in repairLineItems. */
export const workLogs = sqliteTable('work_logs', {
  id: text('id').primaryKey(),
  repairId: text('repair_id').notNull().references(() => repairs.id),
  userId: text('user_id').notNull().references(() => users.id),
  startedAt: integer('started_at', { mode: 'number' }).notNull(),
  endedAt: integer('ended_at', { mode: 'number' }), // null if timer still running
}, (table) => ({
  repairIdIdx: index('work_logs_repair_id_idx').on(table.repairId),
}))

export type WorkLog = typeof workLogs.$inferSelect
export type NewWorkLog = typeof workLogs.$inferInsert

/** Repair status audit trail — every transition recorded */
export const repairStatusHistory = sqliteTable('repair_status_history', {

  'INSERT INTO sales (id, sale_number, customer_id, source_type, source_id, status, subtotal_net, vat_total, total_gross, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)',
  [saleId, saleNumber, saleCustomerId, 'repair', id, 'completed', saleSubtotalNet, saleVatTotal, expectedTotalGross, now]
)

// Insert sale line items (copy from repair line items)
// Note: sale_line_items does NOT have minutes_worked / hourly_rate_snapshot columns
for (const li of lineItems) {
  const saleLineItemId = crypto.randomUUID()
  run(
    `INSERT INTO sale_line_items (id, sale_id, line_type, part_id, labor_service_id, description, quantity, unit_price_net, vat_rate_id, discount_percent, line_total_net, line_total_vat, line_total_gross, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
    [
      saleLineItemId,
      saleId,
      li.lineType,
      li.partId,
      li.laborServiceId,
      li.description,
      Number(li.quantity),
      Number(li.unitPriceNet),
      li.vatRateId,
      li.discountPercent,
      Number(li.lineTotalNet),
      Number(li.lineTotalVat),
      Number(li.lineTotalGross),
      now,
    ]
  )
}

// Insert payment records and allocations for each payment method
for (const pay of validated.payments) {
  const paymentId = crypto.randomUUID()
  run(
    'INSERT INTO payments (id, method, amount, created_at) VALUES (?, ?, ?, ?)',
    [paymentId, pay.method, pay.amount, now]
  )

