  laborLineItemVariant,
  bicycleLineItemVariant,
} from './line-item-variants.js'

// ---------------------------------------------------------------------------
// Quote Status — lifecycle states
// ---------------------------------------------------------------------------

export const quoteStatusSchema = z.enum([
  'draft', 'sent', 'converted', 'rejected'
])

/** A valid quote status */
export type QuoteStatus = z.infer<typeof quoteStatusSchema>

// ---------------------------------------------------------------------------
// Line Item Type
// ---------------------------------------------------------------------------

export const quoteLineItemTypeSchema = z.enum(['part', 'labor', 'bicycle'])

/** A valid line item type for quotes */
export type QuoteLineItemType = z.infer<typeof quoteLineItemTypeSchema>

// ---------------------------------------------------------------------------
// Create Quote Input
// ---------------------------------------------------------------------------

export const createQuoteSchema = z.object({
  customerId: z.string().uuid('customerId must be a valid UUID').optional().nullable(),
  notes: z.string().max(2000).optional().nullable(),
})

/** Input for creating a new quote */
export type CreateQuoteInput = z.infer<typeof createQuoteSchema>

// ---------------------------------------------------------------------------
// Update Quote Input — draft fields only
// ---------------------------------------------------------------------------

export const updateQuoteSchema = z.object({
  customerId: z.string().uuid('customerId must be a valid UUID').optional().nullable(),
  notes: z.string().max(2000).optional().nullable(),
})

/** Input for updating an existing quote (draft fields only) */
export type UpdateQuoteInput = z.infer<typeof updateQuoteSchema>

// ---------------------------------------------------------------------------
// Create Quote Line Item — composed from shared variants
// ---------------------------------------------------------------------------

/** Part line item schema for quotes — allows nullable partId for ad-hoc items */
export const createQuoteLineItemPartSchema = z.object({
  ...partLineItemVariant.toSchema().shape,
  partId: z.string().uuid('partId must be a valid UUID').optional().nullable(),
})

/** Labor line item schema for quotes — uses shared labor variant */
export const createQuoteLineItemLaborSchema = laborLineItemVariant.toSchema()

/** Bicycle line item schema for quotes — uses shared bicycle variant */
export const createQuoteLineItemBicycleSchema = bicycleLineItemVariant.toSchema()

/** Discriminated union for creating a quote line item */
export const createQuoteLineItemSchema = z.discriminatedUnion('lineType', [
  createQuoteLineItemPartSchema,
  createQuoteLineItemLaborSchema,
  createQuoteLineItemBicycleSchema,
])

/** Input for creating a new quote line item */
export type CreateQuoteLineItemInput = z.infer<typeof createQuoteLineItemSchema>

// ---------------------------------------------------------------------------
// Update Quote Line Item — composed from shared variants (partial fields)
// ---------------------------------------------------------------------------

const baseUpdateLineItemFields = {
  description: z.string().min(1, 'description is required').max(500).optional(),
  quantity: z.number().int().positive('quantity must be a positive integer').optional(),
  unitPriceNet: z.number().int().nonnegative('unitPriceNet must be a non-negative integer (cents)').optional(),
  vatRateId: z.string().min(1, 'vatRateId is required').max(50).optional(),
  discountPercent: z.number().int().min(0).max(10000).nullable().optional(), // basis points
}

export const updateQuoteLineItemPartSchema = z.object({
  ...baseUpdateLineItemFields,
  lineType: z.literal('part'),
  partId: z.string().uuid('partId must be a valid UUID').optional().nullable(),
})

export const updateQuoteLineItemLaborSchema = z.object({
  ...baseUpdateLineItemFields,
  lineType: z.literal('labor'),
  laborServiceId: z.string().uuid('laborServiceId must be a valid UUID').optional().nullable(),
})

export const updateQuoteLineItemBicycleSchema = z.object({
  ...baseUpdateLineItemFields,
  lineType: z.literal('bicycle'),
  bicycleId: z.string().uuid('bicycleId must be a valid UUID').optional().nullable(),
  bicycleBrand: z.string().max(100).optional().nullable(),
  bicycleModel: z.string().max(200).optional().nullable(),
  bicycleYear: z.number().int().min(1900).max(new Date().getFullYear() + 1).optional().nullable(),
  bicycleColor: z.string().max(50).optional().nullable(),
  bicycleFrameSize: z.string().max(20).optional().nullable(),
})

/** Discriminated union for updating a quote line item */
export const updateQuoteLineItemSchema = z.discriminatedUnion('lineType', [
  updateQuoteLineItemPartSchema,
  updateQuoteLineItemLaborSchema,
  updateQuoteLineItemBicycleSchema,
])

/** Input for updating an existing quote line item */
export type UpdateQuoteLineItemInput = z.infer<typeof updateQuoteLineItemSchema>

 *
 * @param id - Repair identifier (must be in 'ready' status)
 * @param input - Payment data (single or split methods)
 * @returns CompleteRepairResult with created entities
 */
export async function completeRepairPayment(
  id: string,
  input: CompleteRepairPaymentInput,
): Promise<CompleteRepairResult> {
  // Validate the payment input schema
  const validated = { payments: input.payments }

  if (validated.payments.length === 0) {
    throw new Error('At least one payment method is required')
  }

  // Step 1: Look up current repair state and validate it's in 'ready' status
  const current = await repoFindRepairById(id)
  if (!current) {
    throw new RepairNotFoundError(id)
  }
  if (current.status !== 'ready') {
    throw new RepairNotReadyError(current.status as string)
  }

  // Resolve customerId from repair → bicycle → customer
  const [bicycle] = await db.select().from(bicycles).where(eq(bicycles.id, current.bicycleId))
  let saleCustomerId: string | null = null
  if (bicycle?.customerId) {
    const [cust] = await db.select().from(customers).where(eq(customers.id, bicycle.customerId))
    saleCustomerId = cust?.id ?? null
  }

  // Step 2: Fetch all line items and compute the expected total gross
  const lineItems = await repoFindLineItemsByRepairId(id)
  if (lineItems.length === 0) {
    throw new Error('Cannot complete a repair with no line items')
  }

  let expectedTotalGross = 0
  for (const item of lineItems) {
    expectedTotalGross += Number(item.lineTotalGross)
  }

  // Step 3: Validate payment total matches expected gross total
  const paidTotal = validated.payments.reduce((sum, p) => sum + p.amount, 0)
  if (paidTotal !== expectedTotalGross) {
    throw new PaymentMismatchError(expectedTotalGross, paidTotal)
  }

  // Step 4: Aggregate stock requests from part line items only
  const partLineItems = lineItems.filter(li => li.lineType === 'part')
  const stockRequests: RepairStockCheckRequest[] = partLineItems.map(li => ({
    partId: li.partId!,
    requestedQuantity: Number(li.quantity),
  }))

  // Step 5: Validate stock availability
  const stockResult = await validateRepairStockAvailability(stockRequests)
  if (!stockResult.valid) {
    throw new InsufficientStockForRepairError(stockResult.shortfalls)
  }

  // Step 6: Get sale number from sequence table (atomic increment)
  const updateResult = await db
    .update(sequences)

// Insert sale line items (copy from repair line items)
// Note: sale_line_items does NOT have minutes_worked / hourly_rate_snapshot columns
for (const li of lineItems) {
  const saleLineItemId = crypto.randomUUID()
  run(
    `INSERT INTO sale_line_items (id, sale_id, line_type, part_id, labor_service_id, description, quantity, unit_price_net, vat_rate_id, discount_percent, line_total_net, line_total_vat, line_total_gross, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
    [
      saleLineItemId,
      saleId,
      li.lineType,
      li.partId,
      li.laborServiceId,
      li.description,
      Number(li.quantity),
      Number(li.unitPriceNet),
      li.vatRateId,
      li.discountPercent,
      Number(li.lineTotalNet),
      Number(li.lineTotalVat),
      Number(li.lineTotalGross),
      now,
    ]
  )
}

// Insert payment records and allocations for each payment method
for (const pay of validated.payments) {
  const paymentId = crypto.randomUUID()
  run(
    'INSERT INTO payments (id, method, amount, created_at) VALUES (?, ?, ?, ?)',
    [paymentId, pay.method, pay.amount, now]
  )

  // Insert payment allocation → sale
  run(
    'INSERT INTO payment_allocations (id, payment_id, target_type, target_id, allocated_amount) VALUES (?, ?, ?, ?, ?)',
    [crypto.randomUUID(), paymentId, 'sale', saleId, pay.amount]
  )

  createdPayments.push({ id: paymentId, method: pay.method as 'cash' | 'card' | 'bank_transfer', amount: pay.amount })
}

// Insert stock movements (negative deltas for parts used)
for (const li of partLineItems) {
  const movementId = crypto.randomUUID()
  run(
    'INSERT INTO stock_movements (id, part_id, quantity_delta, reason, reference_type, reference_id, created_at) VALUES (?, ?, ?, ?, ?, ?, ?)',
    [movementId, li.partId!, -Number(li.quantity), 'repair_use', 'sale', saleId, now]
  )

