import { describe, it, expect } from 'vitest'
import {
  paymentMethodSchema,
  cartLineItemSchema,
  createDirectSaleInputSchema,
} from './sales.js'

// ── Payment Method ────────────────────────────────────────────────

describe('paymentMethodSchema', () => {
  it('accepts "cash"', () => {
    const result = paymentMethodSchema.safeParse('cash')
    expect(result.success).toBe(true)
    if (result.success) expect(result.data).toBe('cash')
  })

  it('accepts "card"', () => {
    const result = paymentMethodSchema.safeParse('card')
    expect(result.success).toBe(true)
    if (result.success) expect(result.data).toBe('card')
  })

  it('rejects invalid payment method', () => {
    const result = paymentMethodSchema.safeParse('bank_transfer')
    expect(result.success).toBe(false)
  })

  it('rejects empty string', () => {
    const result = paymentMethodSchema.safeParse('')
    expect(result.success).toBe(false)
  })

  it('rejects null', () => {
    const result = paymentMethodSchema.safeParse(null as unknown as 'cash' | 'card')
    expect(result.success).toBe(false)
  })
})

// ── Cart Line Item ────────────────────────────────────────────────

describe('cartLineItemSchema', () => {
  const validInput = {
    partId: 'part-001',
    quantity: 2,
    unitPriceNet: 5000, // 50.00 in cents
    vatRateId: 'vat-standard',
    description: 'Bolt M6 x 20mm',
  }

  it('accepts a valid line item with all fields', () => {
    const result = cartLineItemSchema.safeParse(validInput)
    expect(result.success).toBe(true)
  })

  it('accepts a valid line item without optional discountPercent', () => {
    const result = cartLineItemSchema.safeParse({ ...validInput, discountPercent: undefined })
    expect(result.success).toBe(true)
  })

  it('accepts a valid line item with null discountPercent (no discount)', () => {
    const result = cartLineItemSchema.safeParse({ ...validInput, discountPercent: null })
    expect(result.success).toBe(true)
  })

  it('accepts a valid line item with positive discountPercent', () => {
    const result = cartLineItemSchema.safeParse({ ...validInput, discountPercent: 10 })
    expect(result.success).toBe(true)
  })

  // ── Rejection cases ────────────────────────────────────────────

  it('rejects missing partId', () => {
    const result = cartLineItemSchema.safeParse({ ...validInput, partId: '' as unknown as string })
    expect(result.success).toBe(false)
  })

  it('rejects negative quantity', () => {
    const result = cartLineItemSchema.safeParse({ ...validInput, quantity: -1 })
    expect(result.success).toBe(false)
  })

  it('rejects zero quantity', () => {
    const result = cartLineItemSchema.safeParse({ ...validInput, quantity: 0 })
    expect(result.success).toBe(false)
  })

  it('rejects non-integer quantity (float)', () => {
    const result = cartLineItemSchema.safeParse({ ...validInput, quantity: 1.5 })
    expect(result.success).toBe(false)
  })

  it('rejects negative unitPriceNet', () => {
    const result = cartLineItemSchema.safeParse({ ...validInput, unitPriceNet: -100 })
    expect(result.success).toBe(false)
  })

  it('accepts zero unitPriceNet (free item)', () => {
    const result = cartLineItemSchema.safeParse({ ...validInput, unitPriceNet: 0 })
    expect(result.success).toBe(true)
  })

  it('rejects non-integer unitPriceNet', () => {
    const result = cartLineItemSchema.safeParse({ ...validInput, unitPriceNet: 123.45 })
    expect(result.success).toBe(false)
  })

  it('rejects missing vatRateId', () => {
    const result = cartLineItemSchema.safeParse({ ...validInput, vatRateId: '' as unknown as string })
    expect(result.success).toBe(false)
